// Package bundled embeds the Redocly-bundled OpenAPI document the server
// serves at GET /api/v1/openapi.json. The JSON is generated by
// scripts/bundle-openapi.mjs; never edit it by hand.
package bundled

import (
	_ "embed"
	"net/http"
	"strconv"
)

//go:embed openapi.json
var document []byte

// Path is where the server mounts the document (ADR 077 prefix).
const Path = "/api/v1/openapi.json"

// Handler serves the embedded OpenAPI document. Mounted on the mux beside
// the ogen API — not an OpenAPI operation — so discovery needs no auth.
func Handler() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			w.Header().Set("Allow", "GET, HEAD")
			http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Cache-Control", "public, max-age=300")
		w.Header().Set("Access-Control-Allow-Origin", "*")
		if r.Method == http.MethodHead {
			w.Header().Set("Content-Length", strconv.Itoa(len(document)))
			return
		}
		_, _ = w.Write(document)
	})
}

// Document returns the embedded OpenAPI JSON bytes.
func Document() []byte {
	return document
}
